        ["npc:rexxar"] = {
            ["public"] = {
                ["body"] = "Rexxar is the Horde's Mok'nathal champion, a beastmaster of mixed orc and ogre ancestry whose bear companion is Misha. He helped secure the Horde's new homeland in Durotar, leading its warriors against Admiral Daelin Proudmoore at Theramore. When Thrall offered him a home afterward, Rexxar chose the wilderness while promising that the Horde could still call upon him.\n\nHe wanders Desolace between Stonetalon and Feralas. His earlier journeys also connect him with Chen Stormstout and the Stonemaul ogres. Rexxar appointed Mok'Morokk to lead the clan, though the overlord's later conduct left his people questioning that choice.",
                ["related"] = {"npc:chen", "npc:mokmorokk"},
                ["sources"] = {"https://warcraft.wiki.gg/wiki/Rexxar_%28Warcraft_III%29", "https://wowpedia.fandom.com/wiki/A_Blaze_of_Glory_%28WC3_Orc%29", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #819; #1166; #1171"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"drakefire_horde_method"},
                    ["body"] = "Rexxar explains that the dormant amulet needs General Drakkisath's blood to become active. He offers to perform the activation, giving the Horde a way through Onyxia's wards.",
                    ["related"] = {"npc:rexxar", "npc:drakkisath", "relic:drakefire-amulet"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6602 description/completion"}
                }
            }
        },
        ["region:4f726772696d6d6172"] = {
            ["public"] = {
                ["body"] = "Orgrimmar is the Horde capital in Durotar, founded by Thrall and named for his predecessor and mentor, Orgrim Doomhammer. It is the center of the orcs' new homeland in Kalimdor. Its districts gather the skills needed to sustain that home: weapon masters and smiths work in the Valley of Honor, shamans teach in the Valley of Wisdom, and the Drag houses craftsmen and their shops. Reports from beyond the gates reach Thrall and his advisers here.\n\nThe Cleft of Shadow houses warlocks, rogues and their suppliers, with an entrance into Ragefire Chasm. The city's trades and traditions bring together the practical work of building a home and the different kinds of power practiced by its people.",
                ["sources"] = {"https://news.blizzard.com/en-gb/article/23156369/wow-classic-city-tour-orgrimmar", "https://worldofwarcraft.blizzard.com/en-us/news/20142853/new-to-world-of-warcraft-welcome-home (city founding and name only; no later city layout)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #831 The Admiral's Orders"},
                ["related"] = {"npc:thrall", "npc:orgrim", "dungeon:ragefire"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.thrall_investigation"},
                    ["body"] = "Thrall suspects traitors within the Horde and seeks a Burning Blade lieutenant's insignia from Skull Rock as the first step in his investigation.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5726 description"},
                    ["related"] = {"place:skull-rock", "faction:burning-blade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.burning_blade_leader"},
                    ["body"] = "Thrall identifies Neeru as the Burning Blade's leader, whose true loyalty is concealed behind a trusted position in Orgrimmar.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description and named objective", "StorageInvestigation/journal-voice/quests_corpus.txt #5727 objectives and description"},
                    ["related"] = {"npc:neeru-fireblade", "faction:burning-blade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.counterplot"},
                    ["body"] = "Thrall directs discreet dealings with Neeru to draw out information about his allies.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description; #5728 description; #5729 description"},
                    ["related"] = {"npc:neeru-fireblade", "npc:thrall"}
                }
            }
        },
        ["npc:neeru-fireblade"] = {
            ["public"] = {
                ["body"] = "Neeru Fireblade is an orc warlock in Orgrimmar's Cleft of Shadow. He presents his study of demonic magic as work against demons and calls his occult research harmless. His expertise attracts requests that a shaman cannot readily answer.\n\nMargoz is prepared to consult him about demonic objects found in Durotar, even while withholding judgment on his assurances. The distinction matters: Neeru's stated purpose explains his public role, while Margoz's willingness to seek his help does not settle whether those assurances are true.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #829 description"},
                ["related"] = {"region:4f726772696d6d6172", "npc:margoz"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.collar_consultation"},
                    ["body"] = "Margoz seeks Neeru's expertise because the demonic searing collars exceed his own powers of divination.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #829 description"},
                    ["related"] = {"npc:margoz", "npc:neeru-fireblade"}
                },
                {
                    ["requires"] = {"neeru.pendant_clue"},
                    ["body"] = "The Eye of Burning Shadow carries a voice threatening Gazz'uz with Neeru's anger. It supplies a troubling connection, without explaining Neeru's role.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #832 description"},
                    ["related"] = {"npc:neeru-fireblade", "place:skull-rock"}
                },
                {
                    ["requires"] = {"neeru.pendant_reply"},
                    ["body"] = "Neeru takes the pendant for study and claims not to understand why its voice named him.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #832 completion"},
                    ["related"] = {"npc:neeru-fireblade"}
                },
                {
                    ["requires"] = {"neeru.burning_blade_leader"},
                    ["body"] = "Thrall identifies Neeru as the Burning Blade's leader, whose true loyalty is concealed behind a trusted position in Orgrimmar.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description and named objective", "StorageInvestigation/journal-voice/quests_corpus.txt #5727 objectives and description"},
                    ["related"] = {"npc:neeru-fireblade", "faction:burning-blade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.counterplot"},
                    ["body"] = "Thrall directs discreet dealings with Neeru to draw out information about his allies.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description; #5728 description; #5729 description"},
                    ["related"] = {"npc:neeru-fireblade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.neeru_reaction"},
                    ["body"] = "Neeru angrily acknowledges Bazzalan and Jergosh's deaths and blames followers of Thrall for the loss.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5729 completion"},
                    ["related"] = {"npc:neeru-fireblade"}
                },
                {
                    ["requires"] = {"neeru.regional_agenda"},
                    ["body"] = "Neeru speaks of preserving the Shadow Council's wider schemes and sending his agents in the Barrens and Ashenvale to pursue a new agenda.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5730 description"},
                    ["related"] = {"npc:neeru-fireblade", "faction:shadow-council"}
                },
                {
                    ["requires"] = {"neeru.taragaman_claim"},
                    ["body"] = "Neeru calls Taragaman the Searing Blade's leader and requests the felguard's heart, claiming the deed will please Thrall.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761 description"},
                    ["related"] = {"npc:neeru-fireblade", "npc:taragaman"}
                },
                {
                    ["requires"] = {"neeru.taragaman_heart"},
                    ["body"] = "Neeru receives Taragaman's heart and promises to report the success to Thrall.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761 completion"},
                    ["related"] = {"npc:neeru-fireblade", "npc:taragaman"}
                }
            }
        },
        ["faction:burning-blade"] = {
            ["public"] = {
                ["body"] = "The Burning Blade name carries a legacy of demonic corruption among the orcs. The clan was broken by that corruption; surviving blademasters who sought to free their brethren from demonic control later joined Thrall's Horde. The Burning Blade cult active in Durotar follows a different cause, spreading demonic influence close to the new Horde's home.\n\nIts coven in the Valley of Trials summons vile familiars, while other cultists occupy Skull Rock. The cult also has a foothold in Desolace, where Horde agents seek to capture its followers' corrupted spirits in enchanted gems. These scattered groups make demonic corruption a danger within the Horde's new homeland as well as beyond its borders.",
                ["sources"] = {"https://classic.battle.net/war3/orc/units/blademaster.shtml", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #792; #794; #827; #1435"},
                ["related"] = {"place:valley-trials", "place:skull-rock", "region:4465736f6c616365"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.burning_blade_leader"},
                    ["body"] = "Thrall identifies Neeru as the Burning Blade's leader, whose true loyalty is concealed behind a trusted position in Orgrimmar.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description and named objective", "StorageInvestigation/journal-voice/quests_corpus.txt #5727 objectives and description"},
                    ["related"] = {"npc:neeru-fireblade", "faction:burning-blade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.counterplot", "neeru.burning_blade_leader"},
                    ["body"] = "Thrall directs discreet dealings with Neeru to draw out information about his allies.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description; #5728 description; #5729 description"},
                    ["related"] = {"npc:neeru-fireblade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.regional_agenda", "neeru.burning_blade_leader"},
                    ["body"] = "Neeru speaks of preserving the Shadow Council's wider schemes and sending his agents in the Barrens and Ashenvale to pursue a new agenda.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5730 description"},
                    ["related"] = {"npc:neeru-fireblade", "faction:shadow-council"}
                }
            }
        },
        ["npc:thrall"] = {
            ["public"] = {
                ["body"] = "Thrall is the orc shaman who leads the Horde from Orgrimmar, bearing Orgrim Doomhammer's armor and hammer. Once enslaved by humans, he now seeks a future in which his people can live freely and recover their shamanic traditions. Even the warlocks he permits in his city recognize that he refuses to abandon his own kin.\n\nA mysterious prophet's warning led him to gather the clans for a voyage to Kalimdor. He freed Grom Hellscream and other captive orcs before sailing from Lordaeron on captured human ships. In Kalimdor, he helped Cairne Bloodhoof's tauren survive their march across the Barrens. He later faced Mannoroth beside Grom, whose fatal victory broke the orcs' demonic blood curse.\n\nAfter the Battle of Mount Hyjal, Thrall founded Durotar, named for his father, and worked to build its capital at Orgrimmar. Rexxar's arrival drew him into defending the new homeland and protecting the Darkspear trolls. His pact with Jaina Proudmoore made him reluctant to strike at human forces near the border, but he authorized resistance if they attacked. Building a home for the Horde required both allies and the resolve to defend them.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 672, 3090)", "https://wowwiki-archive.fandom.com/wiki/Departures", "https://warcraft.blizzplanet.com/chasing-visions-warcraft-iii-reforged/", "https://warcraft.wiki.gg/wiki/The_Long_March_%28WC3_Orc%29", "https://warcraft.wiki.gg/wiki/The_Death_of_Hellscream_%28WC3_Orc%29", "https://warcraft.wiki.gg/wiki/To_Tame_a_Land"},
                ["related"] = {"npc:eitrigg", "npc:orgrim", "region:4f726772696d6d6172"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.thrall_investigation"},
                    ["body"] = "Thrall suspects traitors within the Horde and seeks a Burning Blade lieutenant's insignia from Skull Rock as the first step in his investigation.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5726 description"},
                    ["related"] = {"place:skull-rock", "faction:burning-blade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.counterplot"},
                    ["body"] = "Thrall directs discreet dealings with Neeru to draw out information about his allies.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description; #5728 description; #5729 description"},
                    ["related"] = {"npc:neeru-fireblade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.ashenvale_response"},
                    ["body"] = "Thrall says his spies will investigate the reported presence in Ashenvale.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5730 completion"},
                    ["related"] = {"npc:thrall"}
                }
            }
        },
        ["dungeon:ragefire"] = {
            ["public"] = {
                ["body"] = "Ragefire Chasm is a cavern complex beneath Orgrimmar, entered through the Cleft of Shadow. Lava and deep caves lie below the capital's streets. Troggs occupy the caverns alongside the separate presence of the Searing Blade cult.\n\nThe chasm draws the attention of people beyond the city. Magatha Grimtotem seeks news of Maur, a servant sent to approach the troggs who has failed to return. Its proximity to the capital places these underground inhabitants close to the daily life of the Horde.",
                ["sources"] = {"https://news.blizzard.com/en-gb/article/23156369/wow-classic-city-tour-orgrimmar", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5722 description; #5725 description"},
                ["related"] = {"region:4f726772696d6d6172", "npc:oggleflint", "npc:maur-grimtotem"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.searing_council"},
                    ["body"] = "Varimathras identifies the Searing Blade as a sect of the Shadow Council.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5725 description"},
                    ["related"] = {"faction:shadow-council", "group:searing-blade"}
                },
                {
                    ["requires"] = {"neeru.book_commission"},
                    ["body"] = "The Dark Lady seeks two powerful spell books held by the Searing Blade, commissioning their recovery through Varimathras.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5725 description"},
                    ["related"] = {"npc:varimathras"}
                },
                {
                    ["requires"] = {"neeru.searing_targets"},
                    ["body"] = "Thrall names Bazzalan and Jergosh as Searing Blade leaders valued by Neeru and orders their deaths while preserving the infiltrator's cover.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 description and named objectives", "StorageInvestigation/journal-voice/quests_corpus.txt #5728 objectives and description"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh", "npc:neeru-fireblade"}
                },
                {
                    ["requires"] = {"neeru.searing_deaths"},
                    ["body"] = "Bazzalan and Jergosh are reported slain. The loss disrupts the Searing Blade in Ragefire Chasm.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 completion; #5729 completion"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh"}
                }
            }
        },
        ["group:searing-blade"] = {
            ["public"] = {
                ["body"] = "The Searing Blade is a demonic cult occupying Ragefire Chasm beneath Orgrimmar. Its members share the cavern complex with troggs, establishing a hostile presence close to the Horde's capital. Warlocks and demons are among the forces encountered in those caves.\n\nIts underground setting gives the conflict a local importance: the route into the cult's refuge begins in the Cleft of Shadow, within the city itself.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761 description", "https://news.blizzard.com/en-gb/article/23156369/wow-classic-city-tour-orgrimmar"},
                ["related"] = {"dungeon:ragefire"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.searing_council"},
                    ["body"] = "Varimathras identifies the Searing Blade as a sect of the Shadow Council.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5725 description"},
                    ["related"] = {"faction:shadow-council", "group:searing-blade"}
                },
                {
                    ["requires"] = {"neeru.book_commission"},
                    ["body"] = "The Dark Lady seeks two powerful spell books held by the Searing Blade, commissioning their recovery through Varimathras.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5725 description"},
                    ["related"] = {"npc:varimathras"}
                },
                {
                    ["requires"] = {"neeru.searing_targets"},
                    ["body"] = "Thrall names Bazzalan and Jergosh as Searing Blade leaders valued by Neeru and orders their deaths while preserving the infiltrator's cover.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 description and named objectives", "StorageInvestigation/journal-voice/quests_corpus.txt #5728 objectives and description"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh", "npc:neeru-fireblade"}
                },
                {
                    ["requires"] = {"neeru.searing_deaths"},
                    ["body"] = "Bazzalan and Jergosh are reported slain. The loss disrupts the Searing Blade in Ragefire Chasm.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 completion; #5729 completion"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh"}
                },
                {
                    ["requires"] = {"neeru.neeru_reaction"},
                    ["body"] = "Neeru angrily acknowledges Bazzalan and Jergosh's deaths and blames followers of Thrall for the loss.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5729 completion"},
                    ["related"] = {"npc:neeru-fireblade"}
                }
            }
        },
        ["npc:jergosh"] = {
            ["public"] = {
                ["body"] = "Jergosh the Invoker is a warlock in Ragefire Chasm, the caverns below Orgrimmar. He belongs among the Searing Blade's spellcasters, whose presence shares the chasm with its trogg inhabitants. The route to these caverns lies within the Cleft of Shadow.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 named objectives", "https://news.blizzard.com/en-gb/article/23156369/wow-classic-city-tour-orgrimmar"},
                ["related"] = {"dungeon:ragefire", "group:searing-blade"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.searing_targets"},
                    ["body"] = "Thrall names Bazzalan and Jergosh as Searing Blade leaders valued by Neeru and orders their deaths while preserving the infiltrator's cover.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 description and named objectives", "StorageInvestigation/journal-voice/quests_corpus.txt #5728 objectives and description"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh", "npc:neeru-fireblade"}
