                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 completion; #5729 completion"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh"}
                }
            }
        },
        ["npc:bazzalan"] = {
            ["public"] = {
                ["body"] = "Bazzalan is a satyr in Ragefire Chasm beneath Orgrimmar. He is one of the demonic figures associated with the Searing Blade in the caverns, reached through the Cleft of Shadow. His presence belongs to the chasm's cult forces, distinct from its trogg inhabitants.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 description", "https://news.blizzard.com/en-gb/article/23156369/wow-classic-city-tour-orgrimmar"},
                ["related"] = {"dungeon:ragefire", "group:searing-blade"}
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.searing_targets"},
                    ["body"] = "Thrall names Bazzalan and Jergosh as Searing Blade leaders valued by Neeru and orders their deaths while preserving the infiltrator's cover.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 description and named objectives", "StorageInvestigation/journal-voice/quests_corpus.txt #5728 objectives and description"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh", "npc:neeru-fireblade"}
