    ["quests"] = {
        ["Stormwind Rendezvous"] = {
            ["public"] = {
                ["body"] = "Marshal Windsor is expected at the gates of Stormwind. His allies are called to assemble there before he brings his evidence into the city.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6402"},
                ["related"] = {"npc:windsor"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {}
        },
        ["The Great Masquerade"] = {
            ["public"] = {
                ["body"] = "The Great Masquerade concerns Marshal Windsor's return to Stormwind with evidence for the royal court. The journey begins at the city gates and leads through Stormwind toward the Keep.",
                ["related"] = {"npc:windsor", "region:53746f726d77696e642043697479"},
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6402 Stormwind Rendezvous"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"prestor_identity"},
                    ["body"] = "Lady Katrana Prestor is the identity Onyxia uses at Stormwind's court. The trusted adviser and the black dragon brood mother are the same being.",
                    ["related"] = {"npc:katrana-prestor", "npc:onyxia"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6403 description"}
                },
                {
                    ["requires"] = {"bolvar_control"},
                    ["body"] = "Onyxia has held Bolvar under her control, compromising Stormwind's leadership.",
                    ["related"] = {"npc:bolvar", "npc:onyxia"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6403 description; #7495 completion", "https://warcraft.wiki.gg/wiki/What_the_Wind_Carries (original Thrall dialogue)"},
                    ["unless"] = {"masquerade_aftermath"}
                },
                {
                    ["requires"] = {"masquerade_aftermath"},
                    ["body"] = "Windsor exposes Onyxia before Stormwind's court. The dragon mortally wounds him and escapes, leaving her servants to attack. Bolvar fights the revealed dragonspawn and survives to mourn Windsor, whose sacrifice frees the kingdom from her disguised rule.",
                    ["related"] = {"npc:windsor", "npc:bolvar", "npc:onyxia"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6403 completion", "https://warcraft.wiki.gg/wiki/The_Great_Masquerade (original event ending)"}
                },
                {
                    ["requires"] = {"bolvar_medallion"},
                    ["body"] = "Bolvar's shattered medallion is the instrument through which Onyxia held his mind and body captive. Its breaking ends that magical hold.",
                    ["related"] = {"npc:bolvar"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6403 completion"}
                }
            }
        },
        ["The Dragon's Eye"] = {
            ["public"] = {
                ["body"] = "The Dragon's Eye concerns an enchanted medallion and the search for a dragon able to help restore its magic.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6501"},
                ["related"] = {},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"dragons_eye_mission"},
                    ["body"] = "Bolvar offers a fragment of the medallion and seeks the help of another dragon to turn it into a key. The search is meant to open a way into Onyxia's guarded lair in the Wyrmbog.",
                    ["related"] = {"dungeon:onyxia"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6501 description"}
                }
            }
        },
        ["Drakefire Amulet"] = {
            ["public"] = {
                ["body"] = "The Drakefire Amulet is an enchanted key to Onyxia's lair in Dustwallow Marsh. Its magic allows the bearer to pass the black dragon's wards.",
                ["related"] = {"dungeon:onyxia"},
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6502 Drakefire Amulet; #6602 Blood of the Black Dragon Champion"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"drakefire_alliance_method"},
                    ["body"] = "Haleh identifies the fragment as an enchanted dragon scale. With blood from General Drakkisath, she can restore its magic and make an amulet that overcomes Onyxia's wards.",
                    ["related"] = {"npc:haleh", "npc:drakkisath", "relic:drakefire-amulet"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6502 description/completion"}
                }
            }
        },
        ["What the Wind Carries"] = {
            ["public"] = {
                ["body"] = "Thrall shares intelligence gathered from the Eastern Kingdoms and weighs what it means for the Horde.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6566"},
                ["related"] = {"npc:thrall"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"bolvar_control"},
                    ["body"] = "Onyxia has held Bolvar under her control, compromising Stormwind's leadership.",
                    ["related"] = {"npc:bolvar", "npc:onyxia"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6403 description; #7495 completion", "https://warcraft.wiki.gg/wiki/What_the_Wind_Carries (original Thrall dialogue)"},
                    ["unless"] = {"masquerade_aftermath"}
                },
                {
                    ["requires"] = {"onyxia_court_infiltration", "horde_court_report"},
                    ["body"] = "Thrall's intelligence reports that Onyxia infiltrated Stormwind's royal court in disguise. She was exposed and fled to her lair in Dustwallow Marsh, bringing the threat close to the Horde's settlements.",
                    ["related"] = {},
                    ["sources"] = {"https://warcraft.wiki.gg/wiki/What_the_Wind_Carries (original Thrall dialogue)"},
                    ["unless"] = {"masquerade_aftermath"}
                }
            }
        },
        ["Victory for the Horde"] = {
            ["public"] = {
                ["body"] = "The Head of Onyxia is a dragonslayer's trophy. Bringing it before the leaders of Stormwind or Orgrimmar provides proof of victory over the black dragon brood mother and is an occasion for public honor.",
                ["related"] = {"npc:onyxia"},
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #7490 Victory for the Horde; #7491 For All To See; #7496 Celebrating Good Times"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {}
        },
        ["For All To See"] = {
            ["public"] = {
                ["body"] = "The Head of Onyxia is a dragonslayer's trophy. Bringing it before the leaders of Stormwind or Orgrimmar provides proof of victory over the black dragon brood mother and is an occasion for public honor.",
                ["related"] = {"npc:onyxia"},
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #7490 Victory for the Horde; #7491 For All To See; #7496 Celebrating Good Times"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {}
        },
        ["Victory for the Alliance"] = {
            ["public"] = {
                ["body"] = "The Head of Onyxia is a dragonslayer's trophy. Bringing it before the leaders of Stormwind or Orgrimmar provides proof of victory over the black dragon brood mother and is an occasion for public honor.",
                ["related"] = {"npc:onyxia"},
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #7490 Victory for the Horde; #7491 For All To See; #7496 Celebrating Good Times"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"bolvar_control"},
                    ["body"] = "Onyxia has held Bolvar under her control, compromising Stormwind's leadership.",
                    ["related"] = {"npc:bolvar", "npc:onyxia"},
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6403 description; #7495 completion", "https://warcraft.wiki.gg/wiki/What_the_Wind_Carries (original Thrall dialogue)"},
                    ["unless"] = {"masquerade_aftermath"}
                }
            }
        },
        ["Celebrating Good Times"] = {
            ["public"] = {
                ["body"] = "The Head of Onyxia is a dragonslayer's trophy. Bringing it before the leaders of Stormwind or Orgrimmar provides proof of victory over the black dragon brood mother and is an occasion for public honor.",
                ["related"] = {"npc:onyxia"},
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #7490 Victory for the Horde; #7491 For All To See; #7496 Celebrating Good Times"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {}
        },
        ["Hidden Enemies"] = {
            ["public"] = {
                ["body"] = "Hidden Enemies concerns Thrall's investigation of threats within the Horde's new homeland. The work spans several separate assignments around Orgrimmar and its neighboring caves, drawing on reports brought to the warchief from the capital and its surroundings.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5726-5730"},
                ["related"] = {"npc:thrall", "region:4f726772696d6d6172"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.thrall_investigation"},
                    ["body"] = "Thrall suspects traitors within the Horde and seeks a Burning Blade lieutenant's insignia from Skull Rock as the first step in his investigation.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5726 description"},
                    ["related"] = {"place:skull-rock", "faction:burning-blade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.burning_blade_leader"},
                    ["body"] = "Thrall identifies Neeru as the Burning Blade's leader, whose true loyalty is concealed behind a trusted position in Orgrimmar.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description and named objective", "StorageInvestigation/journal-voice/quests_corpus.txt #5727 objectives and description"},
                    ["related"] = {"npc:neeru-fireblade", "faction:burning-blade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.counterplot"},
                    ["body"] = "Thrall directs discreet dealings with Neeru to draw out information about his allies.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5727 description; #5728 description; #5729 description"},
                    ["related"] = {"npc:neeru-fireblade", "npc:thrall"}
                },
                {
                    ["requires"] = {"neeru.searing_targets"},
                    ["body"] = "Thrall names Bazzalan and Jergosh as Searing Blade leaders valued by Neeru and orders their deaths while preserving the infiltrator's cover.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 description and named objectives", "StorageInvestigation/journal-voice/quests_corpus.txt #5728 objectives and description"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh", "npc:neeru-fireblade"}
                },
                {
                    ["requires"] = {"neeru.searing_deaths"},
                    ["body"] = "Bazzalan and Jergosh are reported slain. The loss disrupts the Searing Blade in Ragefire Chasm.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5728 completion; #5729 completion"},
                    ["related"] = {"npc:bazzalan", "npc:jergosh"}
                },
                {
                    ["requires"] = {"neeru.neeru_reaction"},
                    ["body"] = "Neeru angrily acknowledges Bazzalan and Jergosh's deaths and blames followers of Thrall for the loss.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5729 completion"},
                    ["related"] = {"npc:neeru-fireblade"}
                },
                {
                    ["requires"] = {"neeru.regional_agenda"},
                    ["body"] = "Neeru speaks of preserving the Shadow Council's wider schemes and sending his agents in the Barrens and Ashenvale to pursue a new agenda.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5730 description"},
                    ["related"] = {"npc:neeru-fireblade", "faction:shadow-council"}
                },
                {
                    ["requires"] = {"neeru.ashenvale_response"},
                    ["body"] = "Thrall says his spies will investigate the reported presence in Ashenvale.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5730 completion"},
                    ["related"] = {"npc:thrall"}
                }
            }
        },
        ["Burning Shadows"] = {
            ["public"] = {
                ["body"] = "Burning Shadows concerns the Eye of Burning Shadow, a pendant recovered amid the dangers around Skull Rock. The object's message prompts an inquiry in Orgrimmar.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #832"},
                ["related"] = {"place:skull-rock", "region:4f726772696d6d6172"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.pendant_clue"},
                    ["body"] = "The Eye of Burning Shadow carries a voice threatening Gazz'uz with Neeru's anger. It supplies a troubling connection, without explaining Neeru's role.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #832 description"},
                    ["related"] = {"npc:neeru-fireblade", "place:skull-rock"}
                },
                {
                    ["requires"] = {"neeru.pendant_reply"},
                    ["body"] = "Neeru takes the pendant for study and claims not to understand why its voice named him.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #832 completion"},
                    ["related"] = {"npc:neeru-fireblade"}
                }
            }
        },
        ["Slaying the Beast"] = {
            ["public"] = {
                ["body"] = "Slaying the Beast concerns a dangerous felguard in the caverns beneath Orgrimmar. Ragefire Chasm places demons and hostile cultists close to the Horde capital.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761"},
                ["related"] = {"dungeon:ragefire"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.taragaman_claim"},
                    ["body"] = "Neeru calls Taragaman the Searing Blade's leader and requests the felguard's heart, claiming the deed will please Thrall.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761 description"},
                    ["related"] = {"npc:neeru-fireblade", "npc:taragaman"}
                },
                {
                    ["requires"] = {"neeru.taragaman_heart"},
                    ["body"] = "Neeru receives Taragaman's heart and promises to report the success to Thrall.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5761 completion"},
                    ["related"] = {"npc:neeru-fireblade", "npc:taragaman"}
                }
            }
        },
        ["The Power to Destroy..."] = {
            ["public"] = {
                ["body"] = "The Power to Destroy... concerns powerful magic held in Ragefire Chasm. The caverns beneath Orgrimmar draw the interest of those seeking unusual spellcraft.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5725"},
                ["related"] = {"dungeon:ragefire"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.searing_council"},
                    ["body"] = "Varimathras identifies the Searing Blade as a sect of the Shadow Council.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5725 description"},
                    ["related"] = {"faction:shadow-council", "group:searing-blade"}
                },
                {
                    ["requires"] = {"neeru.book_commission"},
                    ["body"] = "The Dark Lady seeks two powerful spell books held by the Searing Blade, commissioning their recovery through Varimathras.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5725 description"},
                    ["related"] = {"npc:varimathras"}
                },
                {
                    ["requires"] = {"neeru.books_delivered"},
                    ["body"] = "The spell books reach Varimathras, who acknowledges the service to the Dark Lady.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5725 completion"},
                    ["related"] = {"npc:varimathras"}
                }
            }
        },
        ["Neeru Fireblade"] = {
            ["public"] = {
                ["body"] = "Margoz studies demonic corruption in Durotar, while Neeru Fireblade practices warlock magic in Orgrimmar's Cleft of Shadow. Their different expertise provides the setting for this consultation.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #829"},
                ["related"] = {"npc:margoz", "npc:neeru-fireblade"},
                ["contextLabel"] = "Background to the recorded quest"
            },
            ["blocks"] = {
                {
                    ["requires"] = {"neeru.collar_consultation"},
                    ["body"] = "Margoz seeks Neeru's expertise because the demonic searing collars exceed his own powers of divination.",
                    ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #829 description"},
                    ["related"] = {"npc:margoz", "npc:neeru-fireblade"}
                }
            }
        },
        ["The Legend of Stalvan"] = {
            ["public"] = {
                ["body"] = "The Legend of Stalvan is an inquiry in Darkshire. Madame Eva seeks information, and the town hall offers a place to begin tracing a name. The investigation depends on what its records and witnesses can establish.",
                ["sources"] = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt: quest 66"},
                ["related"] = {"place:darkshire"}
            },
            ["blocks"] = {}
        }
    }
})

-- Reviewed 2026-10-16. Exact source/evidence audit: lore-editorial-20261016.
-- No quest completion stands in for unrecorded gossip, loot inspection or a
-- different quest's description. Raw catalogue entries remain the source copy.
do
    local V = "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt"
    local BWL = "https://news.blizzard.com/en-us/article/23302788/wow-classic-descend-into-the-depths-of-blackwing-lair"
    local NX = "https://news.blizzard.com/en-us/article/23572632/wow-classic-naxxramas-is-now-live"
    local notes, quests = {}, {}
    local function Rule(body, sources, related, blocks, title)
        return {public={body=body, sources=sources, related=related or {}, title=title}, blocks=blocks or {}}
    end
    local origin = {requires={"uldaman.origins"},
        body="The stone watcher's account identifies dwarves and troggs as altered descendants of the earthen, beings the Creators fashioned from stone to shape Azeroth's depths.",
        sources={V .. " #2278 completion; https://warcraft.wiki.gg/wiki/Lorekeeper_of_Norgannon (original watcher dialogue)"}, related={"relic:discs-norgannon"}}
    local copy = {requires={"uldaman.copy"}, body="The discs can produce a miniature copy of their records for scholars beyond Uldaman.",
        sources={V .. " #2279 and #2280 descriptions"}}
    local league = {requires={"uldaman.league_analysis"}, body="The Explorers' League regards the recovered discs as possible evidence of the dwarves' enchanted creation. Its scholars still call for careful study of the records.",
        sources={V .. " #2279 completion; #2439 description"}, related={"faction:explorers-league"}}
    local shard = {requires={"blackwing.shard_warning"},
        body="Vaelastrasz says that a scepter shard entrusted to him a thousand years ago is now held by Nefarius. He warns that the black dragon plans to destroy it and urges a champion to recover it quickly.",
        sources={V .. " #8730 description"}, related={"npc:vaelastrasz", "relic:scepter-shifting-sands"}}
    local peace = {requires={"blackwing.shard_returned"}, body="After the shard is returned, Anachronos reports that Vaelastrasz's soul is at peace and that the Aspects are watching the champion's progress.",
        sources={V .. " #8730 completion"}, related={"npc:anachronos"}}
    local phylactery = {requires={"naxx.phylactery"},
        body="Kel'Thuzad's phylactery survives his body's defeat and can allow the lich to reform. Destroying it would prevent his return; the promise of a rich reward instead points its bearer toward Light's Hope Chapel.",
        sources={V .. " #9120 description"}, related={"relic:phylactery-kelthuzad", "place:lights-hope"}}
    local handoff = {requires={"naxx.phylactery_handoff"}, body="Father Montoy eagerly accepts the phylactery and promises a reward. The dangerous vessel passes into his keeping.",
        sources={V .. " #9120 completion"}}

    notes["relic:discs-norgannon"] = Rule(
        "The Discs of Norgannon are ancient platinum records preserved in Uldaman. Their sigils and the stone watcher attending them make the vault a repository of knowledge as well as treasure. The Explorers' League and the sages of Thunder Bluff both take an interest in such finds.",
        {V .. " #2278, #2279 and #2280 descriptions"}, {"dungeon:uldaman"}, {
            {requires={"uldaman.earthen_record"}, body="The watcher identifies the records as an account of the Creators' making of the earthen.", sources={V .. " #2278 description"}}, origin, copy, league})
    notes["npc:archaedas"] = Rule(
        "Archaedas is the Ancient Stone Watcher in Uldaman's depths. He invokes the Makers and calls the vault's stone servants to its defense. The records beyond his post belong to the ancient legacy that draws explorers into these buried halls.",
        {"https://warcraft.wiki.gg/wiki/Archaedas_%28tactics%29 (original encounter dialogue)"}, {"dungeon:uldaman", "relic:discs-norgannon"}, {origin})
    notes["faction:explorers-league"] = Rule(
        "The Explorers' League is Ironforge's archaeological society. Its expeditions search Azeroth for ancient history and clues to the dwarves' beginnings. Reports and requests for blastpowder connect distant digs with the League's headquarters.\n\nIts work also reaches Alterac Valley, where exploration is entangled with the conflict against the Frostwolf. The search for old artifacts can make the ground itself a point of contention.",
        {V .. " #301 Report to Ironforge; #7141 The Battle of Alterac"}, {"dungeon:uldaman", "faction:stormpike"}, {origin, league})
    quests["The Platinum Discs"] = Rule(
        "The Platinum Discs concern the study of ancient records found in Uldaman. Their importance draws the interest of scholars seeking the early history of Azeroth.",
        {V .. " #2278, #2279, #2280, #2439, #2440"}, {"dungeon:uldaman", "relic:discs-norgannon"}, {origin, copy, league})

    notes["faction:hydraxian-waterlords"] = Rule(
        "The Hydraxian Waterlords are water elementals represented by Duke Hydraxis on the coast of Azshara. They wage war against the servants of air, earth and fire, accepting mortal allies who can prove useful in that struggle. Hydraxis regards the purity of water as a source of strength.\n\nTheir campaign reaches from the infected elementals of the Plaguelands to the fire servants beneath Blackrock Mountain. Hydraxis warns that an army is needed to survive the Molten Core, making the Waterlords' elemental war a dangerous undertaking for their mortal allies.",
        {V .. " #6804 Poisoned Water; #6805 Stormers and Rumblers; #6822 The Molten Core; #6823 Agent of Hydraxis"}, {"npc:hydraxis", "dungeon:molten-core"})
    notes["dungeon:blackwing"] = Rule(
        "Blackwing Lair occupies the summit of Blackrock Spire. Here Nefarian, Deathwing's eldest son, experiments with the eggs of different dragonflights, seeking to combine their powers. His laboratories stand behind the armies and dragonkin that hold the upper mountain.\n\nThe lair is both a fortress and a breeding ground. What emerges from Nefarian's experiments threatens to strengthen the black dragonflight far beyond its refuge in Blackrock.",
        {BWL .. " (Classic raid introduction)"}, {"npc:nefarian", "dungeon:blackrock-spire"}, {
            {requires={"blackwing.entry_orders"}, body="Rend Blackhand's orders reveal that the entrance orb admits only bearers of the Mark of Drakkisath. The general guards the brand himself.", sources={V .. " #7761 description"}, related={"npc:drakkisath"}}})
    notes["npc:vaelastrasz"] = Rule(
        "Vaelastrasz is a red dragon who opposes Nefarian in Blackrock Mountain. His aid in the struggle against Rend Blackhand brings a member of the red dragonflight into the conflict within the Spire.",
        {"https://warcraft.wiki.gg/wiki/Vaelastrasz_the_Red (original Upper Blackrock Spire event dialogue)"}, {"faction:red-dragonflight", "dungeon:blackrock-spire"}, {shard, peace}, "Vaelastrasz")
    notes["npc:nefarian"] = Rule(
        "Nefarian is Deathwing's eldest son and the master of Blackwing Lair. From the summit of Blackrock Spire, he experiments with the eggs of other dragonflights, seeking a brood that combines their powers. His armies and laboratories make the upper mountain a stronghold of the black dragonflight.",
        {BWL .. " (Classic raid introduction)"}, {"dungeon:blackwing", "npc:deathwing"}, {shard})
    notes["faction:red-dragonflight"] = Rule(
        "Alexstrasza the Life-Binder leads the red dragonflight, whose charge is the protection of life. During the Second War, the Dragonmaw held her captive through the Demon Soul and forced red dragons into the Horde's service. The flight regained its freedom at Grim Batol and turned against its captors.\n\nRed dragons continue to oppose threats from Deathwing's brood. Vaelastrasz's struggle with Nefarian carries that conflict into Blackrock Mountain.",
        {"https://warcraft.wiki.gg/wiki/Red_dragonflight (original-era history)", "https://warcraft.wiki.gg/wiki/Vaelastrasz_the_Red (original Upper Blackrock Spire event)"}, {"npc:alexstrasza", "event:grim-batol", "npc:vaelastrasz"}, {shard})
    notes["relic:scepter-shifting-sands"] = Rule(
        "The Scepter of the Shifting Sands is bound to the great barrier at Ahn'Qiraj. Restoring it is part of the effort to reopen the fortress while the Horde and Alliance gather the supplies for war. Its history reaches back to the dragons who helped seal the qiraji behind the Scarab Wall.",
        {"https://news.blizzard.com/en-us/article/23482836/wow-classic-ahnqiraj-the-scarab-lords-are-rising (Classic war effort introduction)"}, {"npc:anachronos", "faction:qiraji"}, {shard, peace})
    quests["Nefarius's Corruption"] = Rule(
        "Nefarian's power in Blackrock Mountain threatens those who oppose the black dragonflight. The struggle reaches the dragon's stronghold at the summit of the Spire.",
        {BWL .. " (Classic raid introduction)"}, {"dungeon:blackwing"}, {shard, peace})

    notes["relic:phylactery-kelthuzad"] = {public=false, visibleRequires={"naxx.phylactery"}, blocks={handoff}}
    -- Before the handoff the artifact may be named, but its later recipient may not.
    notes["relic:phylactery-kelthuzad"].public = {
        body="Kel'Thuzad's phylactery is the vessel left after his body's defeat in Naxxramas. Destroying it would prevent the lich from reforming. The promise of a rich reward at Light's Hope Chapel instead offers another destination for the artifact, while the danger of his return remains.",
        sources={V .. " #9120 description"}, related={"npc:kelthuzad", "dungeon:naxxramas"}}
    notes["dungeon:naxxramas"] = Rule(
        "Naxxramas is Kel'Thuzad's floating necropolis above the Eastern Plaguelands. Its quarters gather the Scourge's forces into an army: undead spiders, stitched abominations, plague workers and disciplined death knights. The Argent Dawn prepares to carry the fight into this stronghold.\n\nThe citadel is a place of training and production as well as command. Its horrors serve the next Scourge assault on the living.",
        {NX .. " (Classic introduction and wing descriptions)"}, {"npc:kelthuzad", "faction:scourge", "faction:argent-dawn"}, {phylactery, handoff})
    notes["npc:kelthuzad"] = Rule(
        "Kel'Thuzad is the lich who commands Naxxramas for the Lich King. Once a Kirin Tor archmage, he abandoned Dalaran for forbidden necromancy and founded the Cult of the Damned in Lordaeron. Its plague helped turn the kingdom's people into the Scourge.\n\nArthas killed the necromancer near Andorhal, then later carried his remains to the Sunwell and raised him as a lich. Kel'Thuzad helped summon Archimonde into Azeroth. He now directs another Scourge campaign from the necropolis above the Plaguelands.",
        {"https://warcraft.wiki.gg/wiki/Kel%27Thuzad_and_the_Forming_of_the_Scourge (original history)", "https://warcraft.wiki.gg/wiki/Digging_up_the_Dead (original Warcraft III mission)", "https://warcraft.wiki.gg/wiki/Under_the_Burning_Sky_%28WC3_Undead%29 (original mission)", NX},
        {"dungeon:naxxramas", "npc:arthas", "faction:scourge"}, {phylactery, handoff})
    quests["The Fall of Kel'Thuzad"] = Rule(
        "Kel'Thuzad directs the Scourge from Naxxramas above the Plaguelands. The campaign against the necropolis brings the Argent Dawn into conflict with the lich and the forces he commands.",
        {NX .. " (Classic raid introduction)"}, {"npc:kelthuzad", "dungeon:naxxramas"}, {phylactery, handoff})

    local pieces = {requires={"maraudon.pieces"},
        body="Cavindra says that Vyletongue and Noxxion stole the two parts of her brother Celebras's scepter. She places the satyr beyond the purple crystals and his creation beyond the orange, and asks that the pieces be brought to Celebras.",
        sources={V .. " #7044 description"}, related={"npc:celebras", "npc:vyletongue", "npc:noxxion"}}
    local purpose = {requires={"maraudon.ritual"},
        body="Celebras says the scepter once let him travel quickly through Maraudon while seeking peace for his uncle's spirit. He offers to reunite its rod and diamond through a ritual.",
        sources={V .. " #7046 description"}, related={"relic:scepter-celebras"}}
    local restored = {requires={"maraudon.restored"},
        body="The ritual restores the scepter. Celebras entrusts it to the traveler, asking that its power be used for good and that the journey toward his uncle's remains continue.",
        sources={V .. " #7046 completion"}, related={"relic:scepter-celebras"}}
    notes["dungeon:maraudon"] = Rule("Maraudon's crystal caverns lie beneath Desolace. Princess Theradras, an elemental power of earth, dwells in their depths. Lord Vyletongue's corruption spreads through the outer caves, stunting their plants and poisoning their inhabitants.\n\nPurple and orange crystals distinguish the passages through this troubled sanctuary. The effort to heal its life brings outsiders into conflict with the satyr and the power he has spread.",
        {V .. " #7029, #7044, #7064 and #7065 descriptions"}, {"npc:celebras", "npc:vyletongue"}, {pieces,purpose,restored})
    notes["npc:noxxion"] = Rule("Noxxion is a living manifestation of corruption within Maraudon. Its presence belongs to the poison spreading through the crystal caverns.",
        {V .. " #7044 description"}, {"dungeon:maraudon"}, {pieces})
    notes["npc:vyletongue"] = Rule("Lord Vyletongue is a satyr whose evil spreads through Maraudon's twisting caves. The corruption reaches beyond the satyr himself, afflicting the cavern's inhabitants.",
        {V .. " #7044 description; #7029 Vyletongue Corruption"}, {"dungeon:maraudon"}, {pieces})
    notes["npc:celebras"] = Rule("Celebras wanders Maraudon under a curse. His sister Cavindra seeks help for him as Vyletongue's corruption spreads through the caves.",
        {V .. " #7044 description"}, {"dungeon:maraudon"}, {pieces,purpose,restored}, "Celebras")
    notes["relic:scepter-celebras"] = Rule("The Scepter of Celebras is a relic tied to the druid whose name it bears and to his journey through Maraudon. The corruption in the caverns has interrupted that journey.",
        {V .. " #7044 and #7046"}, {"dungeon:maraudon", "npc:celebras"}, {pieces,purpose,restored})
    quests["Legends of Maraudon"] = Rule("Cavindra seeks help against the corruption afflicting Maraudon and her brother Celebras. Lord Vyletongue's influence has poisoned the twisting caves.",
        {V .. " #7044 description"}, {"dungeon:maraudon", "npc:celebras"}, {pieces})
    quests["The Scepter of Celebras"] = Rule("Celebras's scepter belongs to the troubled history of Maraudon. The relic and its owner are caught in the corruption spreading through the caverns.",
        {V .. " #7044 and #7046"}, {"dungeon:maraudon", "npc:celebras"}, {pieces,purpose,restored})
    notes["npc:nogg"] = Rule("Nogg is a goblin engineer in Orgrimmar's Valley of Honor. A new gnomish rig has outperformed the goblins' shredders, stirring his interest in the rival technology. He hopes to turn gnomish innovations to goblin advantage.",
        {V .. " #2841 Rig Wars"}, {"region:4f726772696d6d6172", "dungeon:gnomeregan"}, {
            {requires={"gnomeregan.safe"}, body="Nogg identifies a safe near Thermaplugg as the location of the rig's blueprints. He says that only Thermaplugg knows its combination and commissions the theft of the plans.", sources={V .. " #2841 description"}, related={"npc:thermaplugg"}},
            {requires={"gnomeregan.plans"}, body="With the plans delivered, Nogg intends to decipher the design and incorporate its innovations into new goblin shredders.", sources={V .. " #2841 completion"}}})

    A.RegisterLoreDiscovery({facts={
        ["uldaman.earthen_record"]={presented={2278},completed={2278}},
        ["uldaman.origins"]={completed={2278}},
        ["uldaman.copy"]={presented={2279,2280},completed={2279,2280}},
        ["uldaman.league_analysis"]={presented={2439},completed={2279,2439}},
        ["blackwing.entry_orders"]={presented={7761},completed={7761}},
        ["blackwing.shard_warning"]={presented={8730},completed={8730}},
        ["blackwing.shard_returned"]={completed={8730}},
        ["naxx.phylactery"]={presented={9120},completed={9120}},
